/* @lc app=leetcode id=1847 lang=kotlin */ class Solution { fun closestRoom(rooms: Array<IntArray>, queries: Array<IntArray>): IntArray = rooms.sortedByDescending { it[1] }.let { rs -> java.util.TreeSet<Int>().let { ts -> IntArray(queries.size).also { ans -> queries.indices.sortedByDescending { queries[it][1] }.fold(0) { p, qi -> (p + generateSequence(p) { it + 1 }.takeWhile { it < rs.size && rs[it][1] >= queries[qi][1] }.onEach { ts.add(rs[it][0]) }.count()).also { ans[qi] = listOfNotNull(ts.floor(queries[qi][0]), ts.ceiling(queries[qi][0])).minWithOrNull(compareBy({ Math.abs(it - queries[qi][0]) }, { it })) ?: -1 } } } } } }